const BlogDetail = () => {
  const { slug } = useParams();
  const post = blogPosts.find((p) => slugify(p.title) === slug);
  if (!post) return <Navigate to="/blogs" replace />;

  const article = articleBodies[slug];
  const Icon = post.icon;

  return (
    <>
      <section className="relative overflow-hidden bg-gradient-to-b from-slate-900 via-sky-950 to-slate-900">
        <div className="absolute inset-0 opacity-[0.05] [background-image:radial-gradient(circle_at_center,_white_1px,transparent_1px)] [background-size:32px_32px]" />
        <div className="absolute -left-32 top-1/3 h-80 w-80 rounded-full bg-sky-500/20 blur-3xl" />

        <div className="relative mx-auto max-w-4xl px-4 pb-20 pt-36 lg:px-6 lg:pb-24 lg:pt-44">
          <Link to="/blogs" className="inline-flex items-center gap-2 text-sm text-sky-400 hover:text-sky-300 transition">
            <ArrowLeft size={16} />
            Back to all articles
          </Link>

          <div className="mt-8 flex items-center gap-2 text-xs font-semibold text-sky-400">
            <Icon size={16} />
            <span>{post.category}</span>
          </div>

          <h1 className="mt-4 font-serif text-4xl font-semibold leading-tight text-white sm:text-5xl">
            {article?.hero || post.title}
          </h1>

          <div className="mt-6 flex flex-wrap items-center gap-5 text-sm text-white/60">
            <span className="flex items-center gap-1.5">
              <User size={15} />
              {article?.author || "SoftCrowd Team"}
            </span>
            <span className="flex items-center gap-1.5">
              <Calendar size={15} />
              {post.date}
            </span>
            <span className="flex items-center gap-1.5">
              <Clock size={15} />
              {post.readTime}
            </span>
          </div>
        </div>
      </section>

      <section className="bg-white px-4 py-16 lg:px-6">
        <article className="mx-auto max-w-3xl">
          {(article?.body || [
            { type: "p", text: post.excerpt },
            { type: "p", text: "Full article content coming soon. This page is the long-form layout that mirrors softcrowdtechnologies.com — each blog card links here." },
          ]).map((block, i) => {
            if (block.type === "h2") {
              return (
                <h2 key={i} className="mt-10 mb-4 font-serif text-2xl font-semibold text-slate-900">
                  {block.text}
                </h2>
              );
            }
            if (block.type === "h3") {
              return (
                <h3 key={i} className="mt-8 mb-3 font-serif text-xl font-semibold text-slate-800">
                  {block.text}
                </h3>
              );
            }
            if (block.type === "ul") {
              return (
                <ul key={i} className="my-6 list-disc space-y-2 pl-6 text-slate-600 leading-relaxed">
                  {block.items.map((item, j) => (
                    <li key={j}>{item}</li>
                  ))}
                </ul>
              );
            }
            return (
              <p key={i} className="my-5 text-lg leading-relaxed text-slate-600">
                {block.text}
              </p>
            );
          })}

          <div className="mt-14 border-t border-slate-200 pt-8">
            <Link
              to="/blogs"
              className="inline-flex items-center gap-2 rounded-full bg-sky-600 px-6 py-3 text-sm font-semibold text-white transition hover:bg-sky-700"
            >
              <ArrowLeft size={16} />
              Explore more articles
            </Link>
          </div>
        </article>
      </section>
    </>
  );
};

export default BlogDetail;